-- FRM-901 — frm901 reslim periodic completion.
--
-- Reslim FRM-901 (Master Sanitation Schedule): the daily per-machine confirmation grid moved to FRM-903.
-- FRM-901 now carries the schedule reference table + a periodic (monthly/6-month) completion record.
--
-- Deployed as status=draft for in-app review before activation (the project workflow). The
-- sop_documents_history trigger fires here because the row is currently active and form_schema is a
-- watched field, so the prior schema is snapshotted (existing draft test entries keep rendering via
-- the revision-matched snapshot; revision is bumped where entries exist). Idempotent on sop_number.

update public.sop_documents set
  revision = 'A',
  status = 'draft',
  content = coalesce(content, '{}'::jsonb) || jsonb_build_object('form_schema', $json${"sections":[{"id":"schedule","title":"Master Sanitation Schedule (reference)","description":"Defines the scheduled cleaning of the facility, equipment, and storage areas \u2014 what is cleaned, how, when, and who is responsible (SQF 11.2.5.1). Daily production-day cleaning is recorded on the Daily Sanitation & Pre-Operation Record (FRM-903) and each machine's SSOP log; periodic cleaning is recorded below as it is completed (SQF 11.2.5.8, 11.2.5.9).","fields":[{"id":"schedule_ref","type":"reference_table","label":"Cleaning schedule","columns":["Area / item to clean","Cleaning method & chemical","Responsible","Frequency"],"rows":[["Food contact surfaces","Clean; sanitize with Sani-512 (1:512, no-rinse)","Sanitation / Production","Daily (production days)"],["Equipment used for production","Cleaned & sanitized per each machine's SOP/SSOP; recorded on its own log","Sanitation / Production","Daily (production days)"],["Utensils used for production","Wash, rinse, sanitize (Sani-512)","Sanitation / Production","Daily (production days)"],["Floors in processing room","Sweep, wash","Sanitation","Daily (production days)"],["Floors in storage areas","Sweep, wash","Sanitation","Daily (production days)"],["Under pallets / bottom rack spaces in storage","Clear and clean","Sanitation","Monthly"],["Dock areas","Sweep, clean","Sanitation","Monthly"],["Overheads","Clean","Sanitation","Every 6 months"],["Racking in storage areas","Clean","Sanitation","Every 6 months"]]}]},{"id":"completion","title":"Periodic Cleaning \u2014 Completion Record","description":"Record each scheduled periodic (monthly / 6-month) cleaning as it is completed, and have it verified. This forms part of the cleaning records required by SQF 11.2.5.9. One record per completed task; the Records report shows completions over time.","fields":[{"id":"task_area","type":"select","label":"Task / area cleaned","width":"half","required":true,"showInList":true,"options":["Under pallets / bottom rack spaces in storage","Dock areas","Overheads","Racking in storage areas","Other (note in comments)"],"allowOther":true},{"id":"frequency","type":"select","label":"Frequency","width":"third","options":["Monthly","Every 6 months","Other"],"required":true,"showInList":true},{"id":"date_completed","type":"date","label":"Date completed","width":"third","required":true,"showInList":true,"defaultToday":true},{"id":"comments","type":"textarea","label":"Method / chemical / comments","width":"full"},{"id":"completed_by","type":"signature","role":"filler","label":"Completed by","width":"half","required":true,"statement":"I completed the cleaning task recorded above."},{"id":"verified_by","type":"signature","role":"verifier","label":"Verified by","width":"half","statement":"I verified this cleaning task was completed to standard."}]}],"settings":{"deletable":false,"attachmentsEnabled":true,"allowMultipleDrafts":true,"requireVerification":false,"instanceTitleTemplate":"{date_completed} \u2014 {task_area}"},"schemaVersion":1}$json$::jsonb)
where sop_number = 'FRM-901';

insert into supabase_migrations.schema_migrations (version, name)
values ('20260727000003', 'frm901_reslim_periodic_completion')
